-- 1) Tarif payroll mulai 1 Maret 2026: batas upah Jaminan Pensiun Rp11.086.300 (BPJS Ketenagakerjaan).
--    Disalin dari baris 2025 (TER PP 58/2023, Pasal 17 UU HPP, PTKP PMK 101/2016 tidak berubah).
INSERT INTO "reference_data" ("id","key","effectiveFrom","data","note","createdAt","updatedAt")
SELECT 'ref-payroll-2026-03', 'payroll', '2026-03-01', jsonb_set("data", '{bpjs,jpWageCap}', '11086300'::jsonb),
  'Batas upah JP Rp11.086.300 mulai 1 Maret 2026. TER PP 58/2023, Pasal 17 UU HPP, PTKP PMK 101/2016, BPJS Kesehatan 4%+1% (batas Rp12 jt), JHT 3,7%+2%, JP 2%+1%, JKM 0,3%.',
  (now() at time zone 'utc'), (now() at time zone 'utc')
FROM "reference_data" WHERE "id" = 'ref-payroll-2025'
ON CONFLICT ("key","effectiveFrom") DO NOTHING;

